def match(pattern: str, text: str) -> bool:
    """
    Implements a basic regex matching algorithm supporting:
    - literal characters
    - '.' (matches any character)
    - '*' (matches zero or more of the preceding element)
    - '+' (matches one or more of the preceding element)

    This implementation uses a recursive approach with memoization to efficiently
    handle overlapping subproblems.
    """
    def is_match(p_index: int, t_index: int, memo: dict) -> bool:
        if (p_index, t_index) in memo:
            return memo[(p_index, t_index)]

        if p_index == len(pattern):
            result = t_index == len(text)
        else:
            first_match = (t_index < len(text) and
                           (pattern[p_index] == text[t_index] or pattern[p_index] == '.'))

            if p_index + 1 < len(pattern):
                if pattern[p_index + 1] == '*':
                    result = (is_match(p_index + 2, t_index, memo) or
                              (first_match and is_match(p_index, t_index + 1, memo)))
                elif pattern[p_index + 1] == '+':
                    result = first_match and is_match(p_index, t_index + 1, memo)
            else:
                result = first_match and is_match(p_index + 1, t_index + 1, memo)

        memo[(p_index, t_index)] = result
        return result

    return is_match(0, 0, {})

