    """
    Implements basic regex matching using a recursive approach to handle 
    literal characters, '.', '*', and '+' operators. The function checks 
    if the pattern matches the entire text.
    """

    def is_match(i: int, j: int) -> bool:
        if j == len(pattern):
            return i == len(text)

        # Check if the current character of the text matches the current character of the pattern
        first_match = i < len(text) and (text[i] == pattern[j] or pattern[j] == '.')

        if j + 1 < len(pattern) and pattern[j + 1] == '*':
            # '*' can either match zero of the preceding element or one or more times
            return is_match(i, j + 2) or (first_match and is_match(i + 1, j))
        elif j + 1 < len(pattern) and pattern[j + 1] == '+':
            # '+' requires at least one occurrence of the preceding element
            return first_match and is_match(i + 1, j)

        return first_match and is_match(i + 1, j + 1)

    return is_match(0, 0)

